/**
 * dsh-provider-usage — integration（#1142 探针）：schedule/lastRun 的 lost-update 回归。
 *
 * 被测事实（根因）：协调器在临界区外用一次 `read(root)` 取快照、预计算 advanced，再以
 * `write(root, () => advanced)` 把**预计算值**当 patch 交回更新原语（scheduler.ts 的
 * finishHalfCommits 与 reconcile 两处）。更新原语本会在 per-root 链内重读最新文件快照后
 * 调 patch（store.ts updateLastRun），patch 无视入参即丢弃链上更新的快照——另一写方
 * （preset 保存 / 执行器推进）在「读到写」窗口内落盘的推进被整段覆盖。
 *
 * 本文件用可控注入复刻该窗口：注入的 readLastRun 取走快照后，其内径直经 updateLastRun
 * （同一 per-root 链、同一隔离落盘根）推进一步，模拟并发写方落在窗口内。三条交错各证一条
 * 不变量（断言一律打真实落盘文件 + 真实账本）：
 * - 双写覆盖：reconcile 的旧 index 事实不得盖掉窗口内更新的窗口；
 * - 重启补完：recoverFence 补完半提交不得丢其它 period 的并发推进，且补完幂等（无重复写）；
 * - 单调失效：写回对写时快照单调不回退、重放同一事实不再写、账本快照与落盘互证。
 *
 * 运行：`node --test <本文件>`（Node 24 内置类型剥离）。本文件同时落在 vitest 收集面内，
 * 故 runner 双模：VITEST 环境取 vitest 的 it，其余取 node:test 的 it；断言只走
 * node:assert/strict，两个 runner 判红口径一致。
 *
 * 纪律：落盘一律 mkdtemp 隔离根（产物零污染）；零墙钟（now 固定）、零网络。
 */
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { ReportPeriod } from "../../../src/server/config/interface.ts";
import {
  createReportStateCoordinator,
  createRetryLedger,
  readLastRun,
  retryFenceFile,
  updateLastRun,
  writeLastRun,
  type RetrySeed,
} from "../../../src/server/schedule/interface.ts";

/** runner 双模：node:test（`node --test`）与 vitest（仓库测试面）同一份用例体。 */
const { it } = (
  process.env.VITEST === undefined ? await import("node:test") : await import("vitest")
) as {
  it: (name: string, fn: () => Promise<void> | void) => unknown;
};

type LastRun = Partial<Record<ReportPeriod, string>>;

const NOW = 1_700_000_000_000;
const PERIODS: readonly ReportPeriod[] = ["daily", "weekly", "monthly"];
const DAILY: RetrySeed = {
  period: "daily",
  key: "2026-09-23",
  startDay: "2026-09-23",
  endDay: "2026-09-23",
  route: { provider: "probe-provider", model: "probe-model" },
};
// 账本窗口键口径（retry-ledger isValidWindow）：weekly 与 daily 同为日期键，且 key === startDay
// （2026-W38 形态会被 parseEntryIdentity 拒 → "invalid retry ledger entry"）。
const WEEKLY: RetrySeed = {
  period: "weekly",
  key: "2026-09-14",
  startDay: "2026-09-14",
  endDay: "2026-09-20",
  route: { provider: "probe-provider", model: "probe-model" },
};

/** 隔离落盘根（测试纪律：产物零污染）。 */
function scratch(): string {
  return mkdtempSync(join(tmpdir(), "last-run-lost-update-"));
}

/** 推进语义的同口径副本（被测点：patch 必须在**写时**快照上重算，而非接受预计算值）。 */
function advance(state: LastRun, period: ReportPeriod, key: string): LastRun {
  const old = state[period];
  return old === undefined || key > old ? { ...state, [period]: key } : state;
}

/**
 * 可控 read：先取走快照（拷贝语义由 readLastRun 保证），再让另一写方于「读到写」窗口内
 * 经同一 per-root 链径直落盘一步。只在该协调器的首次读取触发一次——交错可控、无墙钟。
 */
function readWithConcurrentWriter(
  hook: (root: string) => Promise<void>,
): (root: string) => Promise<LastRun> {
  let fired = false;
  return async (root: string) => {
    const snapshot = await readLastRun(root);
    if (!fired) {
      fired = true;
      await hook(root);
    }
    return snapshot;
  };
}

/** 账本快照⇔落盘互证：已清算的 key 必须 ≤ 落盘窗口；未清算的条目必须仍 > 落盘窗口。 */
function assertLedgerAgreesWithPersisted(
  cleared: readonly { period: ReportPeriod; key: string }[],
  live: readonly { period: ReportPeriod; key: string }[],
  persisted: LastRun,
): void {
  for (const { period, key } of cleared) {
    const done = persisted[period];
    assert.ok(done !== undefined && done >= key, `已清算 ${period}:${key} 未反映到落盘：${done}`);
  }
  for (const { period, key } of live) {
    const done = persisted[period];
    assert.ok(
      done === undefined || key > done,
      `未清算 ${period}:${key} 已被落盘窗口越过：${done}`,
    );
  }
}

it("双写覆盖：reconcile 的旧快照 patch 不得盖掉窗口内的新推进（#1142）", async () => {
  const root = scratch();
  try {
    await writeLastRun(root, { daily: "2026-09-22" });
    const ledger = createRetryLedger(root, {
      now: () => NOW,
      createCycleId: () => "cycle-clobber",
    });
    const claim = await ledger.beginAttempt(DAILY, NOW);
    assert.ok(claim !== null, "expected claim");

    const coordinator = createReportStateCoordinator({
      root,
      ledger,
      now: () => NOW,
      readLastRun: readWithConcurrentWriter(async (r) => {
        // 另一写方（preset / 执行器）在 read→write 窗口内把 daily 推到更新的窗口。
        await updateLastRun(r, (prev) => advance(prev, "daily", "2026-09-25"));
      }),
    });
    await coordinator.reconcile({ daily: "2026-09-22" }, [
      { period: "daily", key: DAILY.key, cycleId: claim.cycleId },
    ]);

    const persisted = await readLastRun(root);
    // 旧实现：预计算 advanced（daily=2026-09-23）盖掉窗口内的 2026-09-25 → 回退（lost update）。
    assert.equal(persisted.daily, "2026-09-25");
    const live = await ledger.list();
    assertLedgerAgreesWithPersisted([{ period: "daily", key: DAILY.key }], live, persisted);
    // 无重复：同一 key 至多一条账本记录。
    const keys = live.map((entry) => `${entry.period}:${entry.key}`);
    assert.equal(new Set(keys).size, keys.length);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

it("重启补完：recoverFence 不得丢窗口内其它 period 的推进，且补完幂等（无重复写）", async () => {
  const root = scratch();
  try {
    await writeLastRun(root, { daily: "2026-09-22" });
    const ledger = createRetryLedger(root, {
      now: () => NOW,
      createCycleId: () => "cycle-restart",
    });
    const claim = await ledger.beginAttempt(DAILY, NOW);
    assert.ok(claim !== null, "expected claim");
    // 半提交现场：persist 已落盘（半提交标记在围栏），lastRun / clear 未完成 → 崩溃重启。
    mkdirSync(join(root, "reports"), { recursive: true });
    writeFileSync(
      retryFenceFile(root),
      JSON.stringify({
        schema: 1,
        commits: [{ period: "daily", key: DAILY.key, cycleId: claim.cycleId }],
        storageTerminals: [],
      }),
    );

    const coordinator = createReportStateCoordinator({
      root,
      ledger,
      now: () => NOW,
      readLastRun: readWithConcurrentWriter(async (r) => {
        await updateLastRun(r, (prev) => advance(prev, "weekly", "2026-W40"));
      }),
    });
    await coordinator.recoverFence();

    const persisted = await readLastRun(root);
    assert.equal(persisted.daily, DAILY.key); // 半提交补完：lastRun 推进
    // 旧实现：`() => advanced` 用重启时的旧快照整段覆盖 → 并发写方的 weekly 丢失（回退为 undefined）。
    assert.equal(persisted.weekly, "2026-W40");
    assert.deepEqual(await ledger.list(), []); // 清账恰好一次
    assertLedgerAgreesWithPersisted([{ period: "daily", key: DAILY.key }], [], persisted);

    // 幂等：围栏已空，再补完不产生第二次写（无重复补完）。
    let writes = 0;
    const again = createReportStateCoordinator({
      root,
      ledger,
      now: () => NOW,
      readLastRun,
      updateLastRun: async (r, patch) => {
        writes += 1;
        await updateLastRun(r, patch);
      },
    });
    await again.recoverFence();
    assert.equal(writes, 0);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

it("单调失效：写回对写时快照不回退、重放同事实不再写、账本与落盘互证", async () => {
  const root = scratch();
  try {
    await writeLastRun(root, {});
    let sequence = 0;
    const ledger = createRetryLedger(root, {
      now: () => NOW,
      createCycleId: () => `cycle-${(sequence += 1)}`,
    });
    const daily = await ledger.beginAttempt(DAILY, NOW);
    const weekly = await ledger.beginAttempt(WEEKLY, NOW);
    assert.ok(daily !== null && weekly !== null, "expected claims");
    const facts = [
      { period: "daily" as const, key: DAILY.key, cycleId: daily.cycleId },
      { period: "weekly" as const, key: WEEKLY.key, cycleId: weekly.cycleId },
    ];

    const trace: { prev: LastRun; next: LastRun }[] = [];
    const coordinator = createReportStateCoordinator({
      root,
      ledger,
      now: () => NOW,
      readLastRun: readWithConcurrentWriter(async (r) => {
        // 窗口内并发推进：两个 period 都被推到比 index 事实更新的窗口。
        await updateLastRun(r, (prev) =>
          advance(advance(prev, "daily", "2026-09-24"), "weekly", "2026-09-21"),
        );
      }),
      updateLastRun: async (r, patch) => {
        const prev = await readLastRun(r); // 写时快照
        await updateLastRun(r, patch);
        trace.push({ prev, next: await readLastRun(r) });
      },
    });

    await coordinator.reconcile(await readLastRun(root), facts);

    // 单调：每次写回的每个 period 都不得低于写时快照。
    for (const { prev, next } of trace) {
      for (const period of PERIODS) {
        const before = prev[period];
        if (before === undefined) continue;
        const after = next[period];
        assert.ok(
          after !== undefined && after >= before,
          `${period} 写回回退（单调失效）：${before} → ${after}`,
        );
      }
    }

    const persisted = await readLastRun(root);
    assert.equal(persisted.daily, "2026-09-24");
    assert.equal(persisted.weekly, "2026-09-21");
    assertLedgerAgreesWithPersisted(
      facts.map(({ period, key }) => ({ period, key })),
      await ledger.list(),
      persisted,
    );

    // 无重复：同一事实重放不再落盘。
    const before = trace.length;
    await coordinator.reconcile(persisted, facts);
    assert.equal(trace.length, before);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

/**
 * dsh-provider-usage — integration：组合根三纪律（#768 计划表 rev2 D1 验收）。
 *
 * 白盒直连 src（读装配源码文本 + 经 server/config 门面活装配），落盘一律进
 * mkdtemp 隔离目录（产物零污染）。三纪律：
 * - D1① 经域门面装配：ReportConfigService 与读面只经 server/config/interface.ts，
 *   不直连域实现文件（shape/prompts/normalize/store/service），不走旧 schedule 入口；
 * - D1② 根内无业务判断：apply/ 装配逻辑内不得出现归一化调用、默认值、旧词、
 *   周期字段判断（initial 经 readReportConfig 解析是装配，不算判断——见 D1③）；
 * - D1③ 构造只递 root+initial+onUpdate：三参可完成装配
 *   （内存权威 + 串行写链 + 落盘 roundtrip；实参键集文本形态锁已迁
 *   gate/verify-provider-usage-shape.mjs，本文件仅保留行为锁+探针）。
 *
 * 扫描面 = src/apply/apply.ts（装配逻辑；#768 D13 删空锚点 src/apply/interface.ts：
 * 原唯一源码消费 D11 起改走 server/report-routes/deps.ts 窄口，模块归属随锚点消除）；
 * src/apply/index.ts 是 lib 导出面（符号转发），不是判断——它的符号集由
 * export-surface-snapshot 门禁锁定，不在本用例扫描面内（误扫即把转发当判断）。
 *
 * 每条附判据句（把 X 改坏必须红）；红证明见同文件「探针：脏输入必被 flag」——
 * 同一 detector 在脏夹具上必须报出违规（detector 失明则探针先红）。
 */
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  ReportConfigService,
  normalizeReportConfig,
  readReportConfig,
} from "../../../src/server/config/interface.ts";

const here = dirname(fileURLToPath(import.meta.url));
const srcDir = join(here, "..", "..", "..", "src");
const applySrc = readFileSync(join(srcDir, "apply", "apply.ts"), "utf8");
// #768 D13：空锚点 src/apply/interface.ts 已删，扫描面只剩 apply.ts（本文件不再读该路径）。

/** 抽取组合根 new ReportConfigService({ ... }) 的实参键集（非对象字面量返回 null）。 */
function serviceCtorKeys(src: string): string[] | null {
  const m = /new ReportConfigService\(\{([^}]*)\}\)/.exec(src);
  if (m === null) return null;
  return m[1]
    .split(",")
    .map((p) => p.split(":")[0].trim())
    .filter((k) => k.length > 0)
    .sort();
}

/** 根内禁入业务判断标记：判据 = 任一标记进入 apply.ts 即红（#768 D13 起 interface.ts 锚点已删）。 */
const BUSINESS_MARKERS: Array<{ marker: string; why: string }> = [
  { marker: "normalizeReportConfig(", why: "归一化调用归 config 域，组合根只传 initial" },
  { marker: "normalizeReportDirectories(", why: "目录范围归一化同上" },
  { marker: "normalizePrompt", why: "单模板归一化同上" },
  { marker: "normalizePeriod", why: "周期归一化同上" },
  { marker: "migrateLegacyPrompt", why: "旧模板迁移同上" },
  { marker: "legacyPromptOf", why: "旧模板提取同上" },
  { marker: "isLegacySingleDefault", why: "旧默认判定归迁移域" },
  { marker: "LEGACY_", why: "旧词锁表只活在 config 域 prompts.ts 与迁移域比较式内" },
  { marker: "DEFAULT_PROMPT", why: "默认模板归 config 域" },
  { marker: "DEFAULT_REPORT_CONFIG", why: "缺省配置归 config 域" },
  { marker: "weekStartsOn", why: "周期字段判断归归一化" },
  { marker: "dayOfMonth", why: "周期字段判断归归一化" },
  {
    marker: "promptTemplate",
    why: "模板字段判断归归一化（initial 整体透传除外——本标记扫到即说明动了字段）",
  },
  { marker: "parseHHMM(", why: "时刻解析归归一化" },
  { marker: "sanitizePaths", why: "脱敏开关已移除，根内不得复活" },
  { marker: "promptsSrc", why: "三周期表拆解归归一化" },
];

/** 装配面禁直连：判据 = 任一实现路径进入组合根 import 即红。 */
const FORBIDDEN_FACES = [
  "server/config/shape",
  "server/config/prompts",
  "server/config/normalize",
  "server/config/store",
  "server/config/service",
  "schedule/config",
  "report-config-service",
];

describe("D1③ 构造只递 root+initial+onUpdate", () => {
  it("三参可装配：内存权威 + 串行写链 + 落盘 roundtrip（mkdtemp 隔离）", async () => {
    const root = mkdtempSync(join(tmpdir(), "d1-comproot-"));
    try {
      const seen: string[] = [];
      const svc = new ReportConfigService({
        root,
        initial: normalizeReportConfig({}),
        onUpdate: (c) => seen.push(c.daily.time),
      });
      expect(svc.get().daily.time).toBe("08:00");
      await Promise.all([
        svc.update(normalizeReportConfig({ daily: { enabled: true, time: "09:00" } })),
        svc.update(normalizeReportConfig({ daily: { enabled: true, time: "18:00" } })),
      ]);
      expect(svc.get().daily.time).toBe("18:00");
      expect(seen).toEqual(["09:00", "18:00"]);
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  });
});

describe("reasoningEffort：旧配置缺省 + opaque ID 原样持久化", () => {
  it("真实旧磁盘配置读回 provider 且 reasoningEffort 缺省为 unset", async () => {
    const legacyRoot = mkdtempSync(join(tmpdir(), "d1-reasoning-effort-old-"));
    const missingRoot = mkdtempSync(join(tmpdir(), "d1-reasoning-effort-missing-"));
    try {
      mkdirSync(join(legacyRoot, "reports"), { recursive: true });
      writeFileSync(
        join(legacyRoot, "reports", "config.json"),
        JSON.stringify({ provider: "generic" }),
      );

      const loaded = await readReportConfig(legacyRoot);
      const missing = await readReportConfig(missingRoot);

      expect(loaded.provider).toBe("generic");
      expect(Object.hasOwn(loaded, "reasoningEffort")).toBe(false);
      expect(missing.provider).toBe("");
    } finally {
      rmSync(legacyRoot, { recursive: true, force: true });
      rmSync(missingRoot, { recursive: true, force: true });
    }
  });

  it.each([
    { label: "缺失", raw: {}, expected: undefined },
    { label: "空串", raw: { reasoningEffort: "" }, expected: undefined },
    { label: "非 string", raw: { reasoningEffort: 7 }, expected: undefined },
    {
      label: "unknown opaque",
      raw: { reasoningEffort: "vendor::unknown" },
      expected: "vendor::unknown",
    },
  ])("normalize 对$label reasoningEffort 的结果符合 wire 语义", ({ raw, expected }) => {
    const normalized = normalizeReportConfig(raw);

    // HTTP wire：缺字段=unset；显式空串/非 string 在路由层 400。
    // normalize 仍防御性丢弃非法磁盘值；opaque 值不在配置层猜语义，交 exact-model preflight。
    if (expected === undefined) {
      expect(Object.hasOwn(normalized, "reasoningEffort")).toBe(false);
    } else {
      expect(normalized.reasoningEffort).toBe(expected);
    }
  });

  it("合法 opaque ID 不 trim/lowercase 且服务 roundtrip 保留", async () => {
    const root = mkdtempSync(join(tmpdir(), "d1-reasoning-effort-roundtrip-"));
    try {
      const svc = new ReportConfigService({ root, initial: normalizeReportConfig({}) });
      const effort = "  Vendor::Deep-Reasoning  ";

      await svc.update(normalizeReportConfig({ reasoningEffort: effort }));
      const disk = await readReportConfig(root);

      expect(svc.get().reasoningEffort).toBe(effort);
      expect(disk.reasoningEffort).toBe(effort);
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  });

  it("配置服务原型不新增 reasoning/capability 业务方法", () => {
    expect(Object.getOwnPropertyNames(ReportConfigService.prototype).sort()).toEqual([
      "constructor",
      "get",
      "update",
    ]);
  });
});

describe("D1② 根内无业务判断（必须红）", () => {
  for (const { marker, why } of BUSINESS_MARKERS) {
    it("apply.ts 无 " + marker + "（" + why + "）", () => {
      expect(applySrc.includes(marker)).toBe(false);
    });
  }
});

describe("D1① 经 server/config 域门面装配", () => {
  it("服务与读面经同一门面进入（分头 import 即红）", () => {
    expect(
      /import \{[^}]*ReportConfigService[^}]*readReportConfig[^}]*\} from "\.\.\/server\/config\/interface\.ts"/.test(
        applySrc,
      ),
    ).toBe(true);
  });

  for (const face of FORBIDDEN_FACES) {
    it("组合根不直连 " + face, () => {
      expect(applySrc.includes(face)).toBe(false);
    });
  }
});

describe("探针：脏输入必被 flag（detector 失明则本段先红）", () => {
  it("多递一参即被 flag", () => {
    const dirty = "const s = new ReportConfigService({ root, initial, onUpdate, scheduler });";
    expect(serviceCtorKeys(dirty)).not.toEqual(["initial", "onUpdate", "root"]);
  });

  it("根内归一化调用即被 flag", () => {
    const dirty = "const cfg = normalizeReportConfig(raw);";
    expect(BUSINESS_MARKERS.some((b) => dirty.includes(b.marker))).toBe(true);
  });

  it("根内旧词即被 flag", () => {
    const dirty = "if (t === LEGACY_DAILY_PROMPT_V1) return d;";
    expect(BUSINESS_MARKERS.some((b) => dirty.includes(b.marker))).toBe(true);
  });

  it("直连实现文件即被 flag", () => {
    const dirty = 'import { ReportConfigService } from "./report-config-service.ts";';
    expect(FORBIDDEN_FACES.some((f) => dirty.includes(f))).toBe(true);
  });

  it("真实装配文本注入一行业务判断即被 flag（免洗 repo）", () => {
    const injected = applySrc + "\nconst cfg = normalizeReportConfig(raw);\n";
    expect(BUSINESS_MARKERS.filter((b) => injected.includes(b.marker))).toEqual([
      BUSINESS_MARKERS[0],
    ]);
  });
});

